import wrapt

class SessionFwd(wrapt.ObjectProxy):
    def __init__(self, target):
        super().__init__(target)
        self._self_revoked = False          # _self_ keeps it off the wrapped object
    def __getattr__(self, name):
        if self._self_revoked: raise CapabilityRevoked(name)
        return super().__getattr__(name)
    def revoke(self):
        self._self_revoked = True

from contextlib import contextmanager

@contextmanager
def lent(target):
    fwd = SessionFwd(target)
    try:
        yield fwd                        # collaborator works inside the block
    finally:
        fwd.revoke()                     # leaving the block always revokes

